    <style>
        *, *::before, *::after { margin:0; padding:0; box-sizing:border-box; }

        :root {
            --primary:      #c84ddf;
            --primary-dark: #68117e;
            --deep:         #260632;
            --mid:          #461256;
            --gold:         #f6af23;
            --gold-dark:    #e09000;
            --success:      #10b981;
            --white:        #ffffff;
            --off-white:    #fdf8ff;
            --text:         #1e0828;
            --text-muted:   #6b5878;
            --border:       rgba(200,77,223,.12);
            --font-sans:    'Inter', system-ui, sans-serif;
            --font-display: 'Plus Jakarta Sans', 'Inter', sans-serif;
            --ease-out:     cubic-bezier(.22,1,.36,1);
            --ease-in-out:  cubic-bezier(.4,0,.2,1);
        }

        html { scroll-behavior: smooth; }

        body {
            font-family: var(--font-sans);
            color: var(--text);
            background: var(--white);
            overflow-x: hidden;
        }

        h1,h2,h3,h4,h5,h6 {
            font-family: var(--font-display);
            letter-spacing: -.025em;
        }

        /* ─── NAVBAR ─────────────────────────────────────────────── */
        .lp-nav {
            position: fixed;
            top: 0; left: 0; right: 0;
            z-index: 1000;
            padding: 1rem 0;
            transition: background .35s var(--ease-in-out),
                        box-shadow .35s var(--ease-in-out),
                        padding .35s var(--ease-in-out);
        }
        .lp-nav.scrolled {
            background: rgba(255,255,255,.92);
            backdrop-filter: blur(20px);
            -webkit-backdrop-filter: blur(20px);
            box-shadow: 0 1px 0 rgba(200,77,223,.1), 0 4px 24px rgba(38,6,50,.07);
            padding: .6rem 0;
        }
        .lp-nav.scrolled .nav-brand-text { color: var(--deep); }
        .lp-nav.scrolled .nav-link-item  { color: #374151; }
        .lp-nav.scrolled .nav-link-item:hover { color: var(--primary-dark); }
        .lp-nav.scrolled .nav-toggle span { background: var(--deep); }

        .nav-inner {
            display: flex;
            align-items: center;
            justify-content: space-between;
            max-width: 1200px;
            margin: 0 auto;
            padding: 0 1.5rem;
        }

        .nav-brand {
            display: flex;
            align-items: center;
            gap: 10px;
            text-decoration: none;
        }
        .nav-brand-icon {
            width: 38px; height: 38px;
            border-radius: 12px;
            background: linear-gradient(135deg, var(--primary-dark), var(--primary));
            display: flex; align-items: center; justify-content: center;
            font-size: 19px;
            color: white;
            flex-shrink: 0;
            box-shadow: 0 4px 12px rgba(200,77,223,.4);
        }
        .nav-brand-text {
            font-family: var(--font-display);
            font-weight: 800;
            font-size: 1.05rem;
            color: white;
            letter-spacing: -.02em;
            line-height: 1.1;
        }
        .nav-brand-text small {
            display: block;
            font-size: .65rem;
            font-weight: 500;
            opacity: .7;
            letter-spacing: .02em;
        }

        .nav-links {
            display: flex;
            align-items: center;
            gap: .25rem;
            list-style: none;
        }
        .nav-link-item {
            color: rgba(255,255,255,.85);
            text-decoration: none;
            font-size: .88rem;
            font-weight: 500;
            padding: .45rem .85rem;
            border-radius: 8px;
            transition: color .2s, background .2s;
        }
        .nav-link-item:hover {
            color: white;
            background: rgba(255,255,255,.12);
        }

        .nav-cta {
            display: flex;
            align-items: center;
            gap: .6rem;
        }
        .btn-nav-login {
            padding: .45rem 1.1rem;
            border-radius: 10px;
            font-size: .88rem;
            font-weight: 600;
            color: rgba(255,255,255,.9);
            border: 1.5px solid rgba(255,255,255,.25);
            background: transparent;
            text-decoration: none;
            transition: .2s;
        }
        .btn-nav-login:hover {
            color: white;
            border-color: rgba(255,255,255,.5);
            background: rgba(255,255,255,.1);
        }
        .lp-nav.scrolled .btn-nav-login {
            color: var(--primary-dark);
            border-color: var(--border);
        }
        .lp-nav.scrolled .btn-nav-login:hover {
            background: rgba(200,77,223,.07);
            border-color: var(--primary);
        }

        .btn-nav-register {
            padding: .45rem 1.2rem;
            border-radius: 10px;
            font-size: .88rem;
            font-weight: 700;
            color: white;
            background: linear-gradient(135deg, var(--primary-dark), var(--primary));
            text-decoration: none;
            border: none;
            transition: transform .2s, box-shadow .2s;
            box-shadow: 0 4px 14px rgba(200,77,223,.35);
        }
        .btn-nav-register:hover {
            transform: translateY(-2px);
            box-shadow: 0 8px 22px rgba(200,77,223,.5);
            color: white;
        }

        .nav-toggle {
            display: none;
            flex-direction: column;
            gap: 5px;
            cursor: pointer;
            padding: 6px;
            background: none;
            border: none;
        }
        .nav-toggle span {
            display: block;
            width: 24px; height: 2px;
            background: white;
            border-radius: 2px;
            transition: .3s var(--ease-in-out);
        }
        .nav-toggle.open span:nth-child(1) { transform: translateY(7px) rotate(45deg); }
        .nav-toggle.open span:nth-child(2) { opacity: 0; transform: scaleX(0); }
        .nav-toggle.open span:nth-child(3) { transform: translateY(-7px) rotate(-45deg); }

        .mobile-menu {
            display: none;
            position: fixed;
            top: 0; left: 0; right: 0; bottom: 0;
            background: rgba(38,6,50,.97);
            backdrop-filter: blur(20px);
            z-index: 999;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            gap: 1.5rem;
            opacity: 0;
            transform: scale(.96);
            transition: opacity .3s, transform .3s;
        }
        .mobile-menu.open {
            display: flex;
            opacity: 1;
            transform: scale(1);
        }
        .mobile-menu a {
            color: white;
            text-decoration: none;
            font-size: 1.4rem;
            font-family: var(--font-display);
            font-weight: 700;
            letter-spacing: -.02em;
            transition: color .2s;
        }
        .mobile-menu a:hover { color: var(--primary); }
        .mobile-close {
            position: absolute;
            top: 1.5rem; right: 1.5rem;
            background: rgba(255,255,255,.1);
            border: none; color: white;
            width: 40px; height: 40px;
            border-radius: 50%;
            font-size: 1.2rem;
            cursor: pointer;
        }

        /* ─── HERO ────────────────────────────────────────────────── */
        .hero {
            min-height: 100vh;
            background: linear-gradient(160deg, var(--deep) 0%, var(--mid) 45%, #8b1fa8 80%, #b83dd0 100%);
            position: relative;
            display: flex;
            align-items: center;
            overflow: hidden;
        }

        /* Animated grid */
        .hero-grid {
            position: absolute;
            inset: 0;
            background-image:
                linear-gradient(rgba(255,255,255,.04) 1px, transparent 1px),
                linear-gradient(90deg, rgba(255,255,255,.04) 1px, transparent 1px);
            background-size: 60px 60px;
            mask-image: radial-gradient(ellipse 80% 80% at 50% 50%, black 30%, transparent 100%);
        }

        /* Glowing orbs */
        .orb {
            position: absolute;
            border-radius: 50%;
            filter: blur(80px);
            pointer-events: none;
        }
        .orb-1 {
            width: 700px; height: 700px;
            background: radial-gradient(circle, rgba(200,77,223,.3) 0%, transparent 70%);
            top: -200px; right: -200px;
            animation: orb-drift-1 12s ease-in-out infinite alternate;
        }
        .orb-2 {
            width: 500px; height: 500px;
            background: radial-gradient(circle, rgba(246,175,35,.2) 0%, transparent 70%);
            bottom: -100px; left: -100px;
            animation: orb-drift-2 15s ease-in-out infinite alternate;
        }
        .orb-3 {
            width: 350px; height: 350px;
            background: radial-gradient(circle, rgba(104,17,126,.4) 0%, transparent 70%);
            top: 40%; left: 30%;
            animation: orb-drift-3 10s ease-in-out infinite alternate;
        }
        @keyframes orb-drift-1 {
            from { transform: translate(0,0) scale(1); }
            to   { transform: translate(-60px, 80px) scale(1.15); }
        }
        @keyframes orb-drift-2 {
            from { transform: translate(0,0) scale(1); }
            to   { transform: translate(50px, -60px) scale(1.2); }
        }
        @keyframes orb-drift-3 {
            from { transform: translate(0,0) scale(1); }
            to   { transform: translate(-40px, 40px) scale(1.1); }
        }

        /* Floating particles */
        .particles { position: absolute; inset: 0; overflow: hidden; pointer-events: none; }
        .particle {
            position: absolute;
            width: 4px; height: 4px;
            background: rgba(255,255,255,.4);
            border-radius: 50%;
            animation: float-particle linear infinite;
        }

        @keyframes float-particle {
            0%   { transform: translateY(100vh) scale(0); opacity: 0; }
            10%  { opacity: 1; }
            90%  { opacity: 1; }
            100% { transform: translateY(-20px) scale(1); opacity: 0; }
        }

        .hero-inner {
            position: relative;
            z-index: 2;
            max-width: 1200px;
            margin: 0 auto;
            padding: 8rem 1.5rem 5rem;
