            color: white;
            line-height: 1.1;
            margin-bottom: 1.25rem;
            animation: fade-up .7s var(--ease-out) .1s both;
        }
        .hero-title .gradient-text {
            background: linear-gradient(90deg, var(--gold), var(--primary), #e879f9);
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            background-clip: text;
        }

        .hero-desc {
            font-size: clamp(.9rem, 1.5vw, 1.05rem);
            color: rgba(255,255,255,.72);
            line-height: 1.75;
            margin-bottom: 2.25rem;
            max-width: 500px;
            animation: fade-up .7s var(--ease-out) .2s both;
        }

        .hero-actions {
            display: flex;
            gap: 1rem;
            flex-wrap: wrap;
            animation: fade-up .7s var(--ease-out) .3s both;
        }

        .btn-hero-primary {
            display: inline-flex;
            align-items: center;
            gap: 8px;
            padding: .9rem 2rem;
            border-radius: 14px;
            font-size: .95rem;
            font-weight: 700;
            color: white;
            background: linear-gradient(135deg, var(--gold-dark), var(--gold));
            text-decoration: none;
            border: none;
            transition: transform .25s, box-shadow .25s;
            box-shadow: 0 8px 24px rgba(246,175,35,.4);
            letter-spacing: -.01em;
        }
        .btn-hero-primary:hover {
            transform: translateY(-3px);
            box-shadow: 0 14px 36px rgba(246,175,35,.55);
            color: white;
        }

        .btn-hero-secondary {
            display: inline-flex;
            align-items: center;
            gap: 8px;
            padding: .9rem 1.8rem;
            border-radius: 14px;
            font-size: .95rem;
            font-weight: 600;
            color: white;
            border: 1.5px solid rgba(255,255,255,.3);
            background: rgba(255,255,255,.08);
            backdrop-filter: blur(8px);
            text-decoration: none;
            transition: .25s;
        }
        .btn-hero-secondary:hover {
            background: rgba(255,255,255,.15);
            border-color: rgba(255,255,255,.5);
            transform: translateY(-2px);
            color: white;
        }

        .hero-trust {
            display: flex;
            align-items: center;
            gap: 1rem;
            margin-top: 2.5rem;
            animation: fade-up .7s var(--ease-out) .4s both;
        }
        .hero-avatars {
            display: flex;
        }
        .hero-avatar {
            width: 34px; height: 34px;
            border-radius: 50%;
            border: 2.5px solid rgba(255,255,255,.3);
            background: linear-gradient(135deg, var(--primary-dark), var(--primary));
            display: flex; align-items: center; justify-content: center;
            font-size: 12px;
            font-weight: 700;
            color: white;
            margin-left: -10px;
        }
        .hero-avatars .hero-avatar:first-child { margin-left: 0; }
        .hero-trust-text {
            font-size: .8rem;
            color: rgba(255,255,255,.7);
            line-height: 1.4;
        }
        .hero-trust-text strong { color: white; display: block; }

        /* Hero visual right side */
        .hero-visual {
            position: relative;
            animation: fade-up .8s var(--ease-out) .2s both;
        }
        .hero-card-main {
            background: rgba(255,255,255,.08);
            backdrop-filter: blur(24px);
            border: 1px solid rgba(255,255,255,.12);
            border-radius: 24px;
            padding: 1.75rem;
            color: white;
        }
        .hero-card-header {
            display: flex;
            align-items: center;
            justify-content: space-between;
            margin-bottom: 1.5rem;
        }
        .hero-card-title {
            font-size: .9rem;
            font-weight: 600;
            opacity: .85;
        }
        .hero-card-live {
            display: flex;
            align-items: center;
            gap: 5px;
            font-size: .72rem;
            color: #34d399;
            font-weight: 600;
        }
        .live-dot {
            width: 7px; height: 7px;
            background: #34d399;
            border-radius: 50%;
            animation: pulse-green 1.5s ease-in-out infinite;
        }
        @keyframes pulse-green {
            0%,100% { box-shadow: 0 0 0 0 rgba(52,211,153,.5); }
            50%      { box-shadow: 0 0 0 5px rgba(52,211,153,0); }
        }

        .stat-row {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 10px;
            margin-bottom: 10px;
        }
        .stat-box {
            background: rgba(255,255,255,.07);
            border: 1px solid rgba(255,255,255,.08);
            border-radius: 14px;
            padding: 14px;
            transition: background .3s, transform .3s;
        }
        .stat-box:hover {
            background: rgba(255,255,255,.12);
            transform: translateY(-2px);
        }
        .stat-box .s-num {
            font-size: 1.6rem;
            font-weight: 800;
            font-family: var(--font-display);
            letter-spacing: -.03em;
            line-height: 1;
            margin: 4px 0 3px;
        }
        .stat-box .s-label {
            font-size: .72rem;
            color: rgba(255,255,255,.6);
            font-weight: 500;
        }
        .stat-box i { font-size: 1rem; }

        .hero-chart {
            background: rgba(255,255,255,.06);
            border: 1px solid rgba(255,255,255,.08);
            border-radius: 14px;
            padding: 16px;
            margin-top: 10px;
        }
        .chart-bars {
            display: flex;
            align-items: flex-end;
            gap: 6px;
            height: 60px;
        }
        .chart-bar {
            flex: 1;
            border-radius: 4px 4px 0 0;
            background: rgba(200,77,223,.4);
            transition: background .3s;
            animation: grow-bar .8s var(--ease-out) both;
        }
        .chart-bar.active { background: linear-gradient(180deg, #c84ddf, #68117e); }
        .chart-bar:hover { background: rgba(200,77,223,.7); }
        @keyframes grow-bar {
            from { transform: scaleY(0); transform-origin: bottom; }
            to   { transform: scaleY(1); transform-origin: bottom; }
        }
        .chart-label {
            display: flex;
            justify-content: space-between;
            margin-top: 8px;
        }
        .chart-label span { font-size: .65rem; color: rgba(255,255,255,.4); }

        /* Floating mini-cards */
        .float-card {
            position: absolute;
            background: white;
            border-radius: 16px;
            padding: 12px 16px;
            box-shadow: 0 20px 60px rgba(0,0,0,.25), 0 0 0 1px rgba(200,77,223,.1);
            animation: float-card 4s ease-in-out infinite alternate;
            z-index: 3;
            white-space: nowrap;
        }
        .float-card-1 {
            bottom: -20px; left: -40px;
            animation-delay: 0s;
        }
        .float-card-2 {
            top: -15px; right: -30px;
            animation-delay: 2s;
        }
        @keyframes float-card {
            from { transform: translateY(0) rotate(-1deg); }
            to   { transform: translateY(-12px) rotate(1deg); }
        }
        .float-card-content {
            display: flex;
            align-items: center;
            gap: 10px;
        }
        .float-icon {
            width: 36px; height: 36px;
            border-radius: 10px;
            display: flex; align-items: center; justify-content: center;
            font-size: 18px;
            flex-shrink: 0;
        }
        .float-card-text { font-family: var(--font-display); }
        .float-card-text .fc-val {
            font-size: 1rem;
            font-weight: 800;
            color: var(--deep);
            line-height: 1;
            letter-spacing: -.02em;
        }
        .float-card-text .fc-lab {
            font-size: .7rem;
            color: var(--text-muted);
            font-weight: 500;
        }

        @keyframes fade-up {
            from { opacity: 0; transform: translateY(28px); }
            to   { opacity: 1; transform: translateY(0); }
        }

        /* Hero scroll indicator */
        .scroll-indicator {
            position: absolute;
            bottom: 2.5rem;
            left: 50%;
            transform: translateX(-50%);
            display: flex;
            flex-direction: column;
            align-items: center;
            gap: 8px;
            color: rgba(255,255,255,.5);
            font-size: .72rem;
            font-weight: 500;
            letter-spacing: .06em;
            text-transform: uppercase;
            animation: fade-up 1s var(--ease-out) .8s both;
            z-index: 2;
        }
        .scroll-mouse {
            width: 22px; height: 36px;
            border: 2px solid rgba(255,255,255,.3);
            border-radius: 11px;
            display: flex;
            justify-content: center;
            padding-top: 6px;
        }
        .scroll-wheel {
            width: 4px; height: 8px;
            background: rgba(255,255,255,.6);
            border-radius: 2px;
            animation: scroll-down 1.5s ease-in-out infinite;
        }
        @keyframes scroll-down {
            0%   { transform: translateY(0); opacity: 1; }
            100% { transform: translateY(8px); opacity: 0; }
        }

        /* ─── STATS STRIP ─────────────────────────────────────────── */
        .stats-strip {
            background: var(--off-white);
            border-top: 1px solid rgba(200,77,223,.08);
            border-bottom: 1px solid rgba(200,77,223,.08);
            padding: 2.5rem 0;
        }
        .stats-strip-inner {
            max-width: 1100px;
            margin: 0 auto;
            padding: 0 1.5rem;
            display: grid;
            grid-template-columns: repeat(4, 1fr);
            gap: 1rem;
        }
        .stat-item {
            text-align: center;
            padding: 1rem;
            border-right: 1px solid rgba(200,77,223,.1);
            transition: transform .3s;
        }
        .stat-item:last-child { border-right: none; }
        .stat-item:hover { transform: translateY(-3px); }
        .stat-item .si-num {
            font-size: clamp(1.8rem, 3vw, 2.4rem);
            font-weight: 900;
            font-family: var(--font-display);
            background: linear-gradient(135deg, var(--deep), var(--primary));
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            background-clip: text;
            letter-spacing: -.03em;
            line-height: 1;
        }
        .stat-item .si-label {
            font-size: .82rem;
            color: var(--text-muted);
            font-weight: 500;
            margin-top: .4rem;
        }

        /* ─── SECTION COMMONS ─────────────────────────────────────── */
        .section-eyebrow {
            display: inline-flex;
            align-items: center;
            gap: 6px;
            background: rgba(200,77,223,.08);
            border: 1px solid rgba(200,77,223,.15);
            border-radius: 50px;
            padding: 5px 14px;
            font-size: .76rem;
            font-weight: 700;
            color: var(--primary-dark);
            text-transform: uppercase;
            letter-spacing: .06em;
            margin-bottom: 1rem;
        }
        .section-title {
            font-size: clamp(1.7rem, 3vw, 2.5rem);
            font-weight: 800;
            color: var(--deep);
            line-height: 1.2;
            margin-bottom: .75rem;
        }
        .section-subtitle {
            font-size: clamp(.88rem, 1.5vw, 1rem);
            color: var(--text-muted);
            line-height: 1.7;
            max-width: 560px;
        }

        .section-pad { padding: 6rem 0; }
        .section-pad-sm { padding: 4rem 0; }

        .container-lp {
            max-width: 1200px;
            margin: 0 auto;
            padding: 0 1.5rem;
        }

        /* ─── FEATURES ───────────────────────────────────────────── */
        .features-bg {
            background: var(--off-white);
        }

        .features-grid {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: 1.5rem;
            margin-top: 3.5rem;
        }

        .feature-card {
            background: white;
            border: 1px solid var(--border);
            border-radius: 22px;
            padding: 2rem;
            transition: transform .3s var(--ease-out), box-shadow .3s;
            position: relative;
            overflow: hidden;
        }
        .feature-card::before {
            content: '';
            position: absolute;
            inset: 0;
            background: linear-gradient(135deg, rgba(200,77,223,.03), transparent);
            opacity: 0;
            transition: opacity .3s;
        }
        .feature-card:hover {
            transform: translateY(-6px);
            box-shadow: 0 20px 50px rgba(38,6,50,.1);
        }
        .feature-card:hover::before { opacity: 1; }

        .fc-icon {
            width: 52px; height: 52px;
            border-radius: 16px;
            display: flex; align-items: center; justify-content: center;
            font-size: 24px;
            margin-bottom: 1.25rem;
        }
        .fc-title {
            font-size: 1.05rem;
            font-weight: 700;
            color: var(--deep);
            margin-bottom: .5rem;
        }
        .fc-desc {
            font-size: .87rem;
            color: var(--text-muted);
            line-height: 1.65;
        }

        .fc-tag {
            display: inline-flex;
            align-items: center;
            gap: 5px;
            margin-top: 1rem;
            font-size: .72rem;
            font-weight: 600;
            color: var(--primary-dark);
        }

        /* Feature highlight card */
        .feature-card.highlight {
            background: linear-gradient(160deg, var(--deep) 0%, var(--mid) 100%);
            border-color: transparent;
            color: white;
        }
        .feature-card.highlight .fc-title { color: white; }
        .feature-card.highlight .fc-desc  { color: rgba(255,255,255,.7); }
        .feature-card.highlight .fc-tag   { color: var(--gold); }
        .feature-card.highlight .fc-tag i { color: var(--gold); }

        /* ─── HOW IT WORKS ───────────────────────────────────────── */
        .how-inner {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 5rem;
            align-items: center;
        }

        .steps-list { list-style: none; margin-top: 2rem; }
        .step-item {
            display: flex;
            gap: 1.25rem;
            padding: 1.25rem 0;
            border-bottom: 1px solid rgba(200,77,223,.07);
            transition: .25s;
            cursor: default;
            border-radius: 12px;
            position: relative;
        }
        .step-item:last-child { border-bottom: none; }
        .step-item:hover { background: rgba(200,77,223,.04); padding-left: .75rem; }

        .step-num {
            width: 44px; height: 44px;
            border-radius: 14px;
            background: linear-gradient(135deg, var(--deep), var(--primary-dark));
            color: white;
            display: flex; align-items: center; justify-content: center;
            font-size: .85rem;
            font-weight: 800;
            flex-shrink: 0;
            transition: transform .25s;
            box-shadow: 0 6px 18px rgba(38,6,50,.2);
        }
        .step-item:hover .step-num { transform: scale(1.08) rotate(-4deg); }
        .step-body {}
        .step-title {
            font-size: .95rem;
            font-weight: 700;
            color: var(--deep);
            margin-bottom: .25rem;
        }
        .step-desc { font-size: .83rem; color: var(--text-muted); line-height: 1.6; }

        /* How visual */
        .how-visual {
            position: relative;
        }
        .dashboard-mockup {
            background: linear-gradient(160deg, var(--deep), var(--mid));
            border-radius: 24px;
            padding: 1.5rem;
            box-shadow: 0 40px 80px rgba(38,6,50,.25);
            position: relative;
            overflow: hidden;
        }
        .dashboard-mockup::before {
            content: '';
            position: absolute;
            top: -50px; right: -50px;
            width: 200px; height: 200px;
            background: radial-gradient(circle, rgba(200,77,223,.3), transparent);
            pointer-events: none;
        }
        .db-topbar {
            display: flex;
            align-items: center;
            gap: 6px;
            margin-bottom: 1rem;
            padding-bottom: 1rem;
            border-bottom: 1px solid rgba(255,255,255,.08);
        }
        .db-dot {
            width: 10px; height: 10px;
            border-radius: 50%;
        }
        .db-url {
            flex: 1;
            background: rgba(255,255,255,.06);
            border-radius: 6px;
            padding: 5px 10px;
            font-size: .7rem;
            color: rgba(255,255,255,.4);
            font-family: monospace;
            margin-left: 6px;
        }

        .db-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-bottom: 10px; }
        .db-stat-card {
            background: rgba(255,255,255,.07);
            border: 1px solid rgba(255,255,255,.08);
            border-radius: 12px;
            padding: 12px;
            color: white;
        }
        .db-stat-card .db-s-label { font-size: .65rem; color: rgba(255,255,255,.5); font-weight: 500; text-transform: uppercase; letter-spacing: .04em; }
        .db-stat-card .db-s-val {
            font-size: 1.4rem;
            font-weight: 800;
            font-family: var(--font-display);
            letter-spacing: -.02em;
            margin-top: 2px;
        }
        .db-stat-card .db-s-trend {
            font-size: .68rem;
            color: #34d399;
            font-weight: 600;
            margin-top: 2px;
        }

        .db-chart-area {
            background: rgba(255,255,255,.05);
            border: 1px solid rgba(255,255,255,.07);
            border-radius: 12px;
            padding: 14px;
        }
        .db-chart-label {
            font-size: .7rem;
            color: rgba(255,255,255,.5);
            margin-bottom: 10px;
            font-weight: 500;
        }
        .db-bars {
            display: flex;
            align-items: flex-end;
            gap: 5px;
            height: 50px;
        }
        .db-bar {
            flex: 1;
            background: rgba(200,77,223,.35);
            border-radius: 3px 3px 0 0;
        }
        .db-bar.hi { background: linear-gradient(180deg, var(--primary), var(--primary-dark)); }

        .db-students {
            margin-top: 10px;
            background: rgba(255,255,255,.05);
            border: 1px solid rgba(255,255,255,.07);
            border-radius: 12px;
            overflow: hidden;
        }
        .db-student-row {
            display: flex;
            align-items: center;
            gap: 10px;
            padding: 9px 12px;
            border-bottom: 1px solid rgba(255,255,255,.05);
            font-size: .72rem;
            color: rgba(255,255,255,.8);
        }
        .db-student-row:last-child { border-bottom: none; }
        .db-s-avatar {
            width: 26px; height: 26px;
            border-radius: 8px;
            background: linear-gradient(135deg, var(--primary-dark), var(--primary));
            display: flex; align-items: center; justify-content: center;
            font-size: 11px;
            font-weight: 700;
            color: white;
            flex-shrink: 0;
        }
        .db-s-badge {
            margin-left: auto;
            padding: 2px 8px;
            border-radius: 20px;
            font-size: .63rem;
            font-weight: 600;
        }
        .db-s-badge.aktif { background: rgba(52,211,153,.15); color: #34d399; }
        .db-s-badge.baru  { background: rgba(200,77,223,.2); color: #e879f9; }

        /* ─── ROLES ───────────────────────────────────────────────── */
        .roles-bg { background: linear-gradient(180deg, var(--off-white) 0%, white 100%); }

        .roles-grid {
            display: grid;
            grid-template-columns: repeat(4, 1fr);
            gap: 1.25rem;
            margin-top: 3rem;
        }

        .role-card {
            border-radius: 22px;
            padding: 2rem 1.5rem;
            text-align: center;
            transition: transform .3s var(--ease-out), box-shadow .3s;
            position: relative;
            overflow: hidden;
            cursor: default;
        }
        .role-card:hover {
            transform: translateY(-8px);
            box-shadow: 0 24px 60px rgba(38,6,50,.14);
        }
        .role-card .rc-icon {
            width: 64px; height: 64px;
            border-radius: 50%;
            margin: 0 auto 1.25rem;
            display: flex; align-items: center; justify-content: center;
            font-size: 28px;
        }
        .role-card .rc-role {
            font-size: .7rem;
            font-weight: 700;
            text-transform: uppercase;
            letter-spacing: .08em;
            margin-bottom: .35rem;
        }
        .role-card .rc-title {
            font-size: 1rem;
            font-weight: 800;
            margin-bottom: .6rem;
            letter-spacing: -.02em;
        }
        .role-card .rc-desc {
            font-size: .82rem;
            line-height: 1.6;
        }
        .role-card .rc-features {
            list-style: none;
            margin-top: 1rem;
            display: flex;
            flex-direction: column;
            gap: 5px;
            text-align: left;
        }
        .role-card .rc-features li {
            font-size: .78rem;
            display: flex;
            align-items: center;
            gap: 7px;
        }
        .role-card .rc-features li i { font-size: 11px; flex-shrink: 0; }

        /* Owner */
        .role-owner {
            background: linear-gradient(160deg, var(--deep) 0%, #3a0950 100%);
            color: white;
        }
        .role-owner .rc-icon { background: rgba(200,77,223,.2); color: #e879f9; }
        .role-owner .rc-role { color: rgba(255,255,255,.5); }
        .role-owner .rc-title { color: white; }
        .role-owner .rc-desc  { color: rgba(255,255,255,.65); }
        .role-owner .rc-features li { color: rgba(255,255,255,.75); }
        .role-owner .rc-features li i { color: #c84ddf; }

        /* Admin */
        .role-admin {
            background: linear-gradient(160deg, #1e1b4b, #312e81);
            color: white;
        }
        .role-admin .rc-icon { background: rgba(99,102,241,.2); color: #818cf8; }
        .role-admin .rc-role { color: rgba(255,255,255,.5); }
        .role-admin .rc-title { color: white; }
        .role-admin .rc-desc  { color: rgba(255,255,255,.65); }
        .role-admin .rc-features li { color: rgba(255,255,255,.75); }
        .role-admin .rc-features li i { color: #818cf8; }

        /* Guru */
        .role-guru {
            background: white;
            border: 1px solid rgba(16,185,129,.15);
        }
        .role-guru .rc-icon { background: rgba(16,185,129,.1); color: #059669; }
        .role-guru .rc-role { color: #059669; }
        .role-guru .rc-title { color: var(--deep); }
        .role-guru .rc-desc  { color: var(--text-muted); }
        .role-guru .rc-features li { color: #374151; }
        .role-guru .rc-features li i { color: #10b981; }

        /* Siswa */
        .role-siswa {
            background: white;
            border: 1px solid rgba(246,175,35,.2);
        }
        .role-siswa .rc-icon { background: rgba(246,175,35,.1); color: var(--gold-dark); }
        .role-siswa .rc-role { color: var(--gold-dark); }
        .role-siswa .rc-title { color: var(--deep); }
        .role-siswa .rc-desc  { color: var(--text-muted); }
        .role-siswa .rc-features li { color: #374151; }
        .role-siswa .rc-features li i { color: var(--gold); }

        /* ─── TESTIMONIALS ───────────────────────────────────────── */
        .testimonials-bg {
            background: linear-gradient(135deg, var(--deep) 0%, var(--mid) 50%, #8b1fa8 100%);
            position: relative;
            overflow: hidden;
        }
        .testimonials-bg::before {
            content: '';
            position: absolute;
            inset: 0;
